// A type with a non-throwing move constructor
class Widget {
public:
    // ... other members
    Widget(Widget&& other) noexcept { /* cheap resource transfer */ }
    Widget& operator=(Widget&& other) noexcept { /* cheap resource transfer */ return *this; }
};

// A type whose move constructor is NOT marked noexcept
class Gadget {
public:
    // ... other members
    Gadget(Gadget&& other) { /* cheap resource transfer that could throw */ }
    Gadget& operator=(Gadget&& other) { /* ... */ return *this; }
};

// std::vector<Widget> will use move on reallocation.
// std::vector<Gadget> will use copy on reallocation to maintain
// the strong exception safety guarantee.
